        private JMenuBar menuBar(){JMenuBar bar=new JMenuBar();if(!session.transientDesktop){JMenu file=new JMenu("File");file.add(item("New Project…",()->{if(confirmLeave())DesktopMain.runWizard(this,true);}));file.add(item("Open Project…",()->{if(confirmLeave())DesktopMain.runWizard(this,false);}));JMenu recent=new JMenu("Open Recent");DesktopPreferences preferences=DesktopPreferences.load(DesktopPreferences.defaultFile());if(preferences.recentProjects.isEmpty())recent.setEnabled(false);for(DesktopPreferences.RecentProject entry:preferences.recentProjects)recent.add(item(entry.toString(),()->{if(confirmLeave())DesktopMain.openRecent(this,entry);}));file.add(recent);file.addSeparator();file.add(item("Save",this::save));file.add(item("Save As…",this::saveAs));file.add(item("Choose Export Folder…",this::chooseExport));file.addSeparator();file.add(item("Exit",this::attemptExit));bar.add(file);}JMenu npc=new JMenu("NPC");npc.add(item("Browse NPCs…",this::browseNpcs));npc.add(item("Compatibility Details",this::showDiagnostics));bar.add(npc);JMenu advanced=new JMenu("Advanced");advanced.add(item("Manual animation sources…",this::showManualSources));bar.add(advanced);JMenu help=new JMenu("Help");help.add(item("About",()->JOptionPane.showMessageDialog(this,"RSC Sprite Baker\nChoose a direction, customize its poses, and export PNG + provenance.\n\nDefault desktop work is temporary until exported.","About",JOptionPane.INFORMATION_MESSAGE)));bar.add(help);return bar;}
        private JMenuItem item(String label,Runnable action){JMenuItem item=new JMenuItem(label);item.addActionListener(e->action.run());return item;}
        private void save(){SpriteProject snapshot=project.copy();long version=editVersion;runAsync("Saving project…",()->{snapshot.save(session.projectFile);DesktopMain.remember(session);return session.projectFile;},path->{if(version==editVersion)session.dirty=false;updateTitle();status.setText("Saved "+path);});}
        private void saveAs(){Path selected=DesktopMain.chooseProject(this,true);if(selected==null)return;session.projectFile=selected;save();updateTitle();}
        private void chooseExport(){Path selected=DesktopMain.chooseDirectory(this,"Select export folder",session.exportDirectory);if(selected==null)return;session.exportDirectory=selected.toAbsolutePath().normalize();DesktopMain.remember(session);status.setText("Export folder: "+session.exportDirectory);}
        private void markDirty(){session.dirty=true;editVersion++;assembledRender=null;stopPlaybacks();updateTitle();}
        private boolean confirmLeave(){if(!session.dirty)return true;if(session.transientDesktop){int choice=JOptionPane.showOptionDialog(this,"Adjustments for NPC "+project.npcId+" have not been exported.\nSwitching or closing will discard them.","Discard unexported adjustments?",JOptionPane.DEFAULT_OPTION,JOptionPane.WARNING_MESSAGE,null,new String[]{"Discard Adjustments","Keep Editing"},"Keep Editing");return choice==0;}int choice=JOptionPane.showConfirmDialog(this,"Save changes to "+session.projectFile.getFileName()+" before continuing?","Unsaved changes",JOptionPane.YES_NO_CANCEL_OPTION,JOptionPane.WARNING_MESSAGE);if(choice==JOptionPane.CANCEL_OPTION||choice==JOptionPane.CLOSED_OPTION)return false;if(choice==JOptionPane.YES_OPTION)try{project.save(session.projectFile);session.dirty=false;DesktopMain.remember(session);updateTitle();}catch(Exception e){error(e);return false;}return true;}
        private void attemptClose(){if(confirmLeave()){stopPlaybacks();dispose();}}
        private void attemptExit(){if(confirmLeave()){stopPlaybacks();DesktopMain.exitApplication();}}
        private void browseNpcs(){new NpcBrowserDialog(this,session.cacheDirectory,entry->{if(!confirmLeave())return;try{stopPlaybacks();DesktopSession next;if(session.transientDesktop)next=DesktopWorkflow.transientSession(session.cacheDirectory,session.exportDirectory,entry.id);else{Path selected=DesktopMain.chooseProject(this,true);if(selected==null)return;next=DesktopWorkflow.create(session.cacheDirectory,selected,session.exportDirectory,entry.id);}DesktopMain.openSession(this,next);}catch(Exception e){error(e);}}).setVisible(true);}
        private void showDiagnostics(){tasks.submit("Refreshing compatibility diagnostics…",()->TextureDiagnostics530.analyze(workspace.baseModel,workspace.npc,workspace.textures),report->JOptionPane.showMessageDialog(this,report.summary()+"\nMaterials: "+report.materialIds+"\nType-0 mappings: "+report.type0Mappings+"\nAdvanced mappings: "+report.advancedMappingFallbacks+"\nErrors: "+report.errors,"NPC "+project.npcId+" compatibility",report.supported()?JOptionPane.INFORMATION_MESSAGE:JOptionPane.WARNING_MESSAGE),this::error);}
        private void loadCompatibility(){tasks.submit("Checking compatibility…",()->TextureDiagnostics530.analyze(workspace.baseModel,workspace.npc,workspace.textures),report->{materialStatus.setText(report.summary());materialStatus.setForeground(report.supported()?new Color(25,110,55):new Color(170,35,35));},this::error);}
        private void loadCombatCandidates(){combatCandidates.removeAllItems();tasks.submit("Detecting combat motion from the side view…",()->AnimationDiscovery.combatCandidates(workspace),found->{for(CombatCandidate candidate:found)combatCandidates.addItem(candidate);combatCandidates.setToolTipText("Advanced override choices ranked by side-view departure from standing and walking");CombatCandidate selected=null;for(CombatCandidate candidate:found)if(candidate.sequenceId==project.combatSequenceId){selected=candidate;break;}if(selected==null&&!found.isEmpty()&&(project.combatSequenceId<0||combatColumnIsAutomatic())){selected=found.get(0);directionBrowser.assign(DirectionFrameBrowser.Source.COMBAT,selected.sequenceId);markDirty();}if(selected!=null){recommendedCombat=selected.suggestions();applyCombatSuggestions(recommendedCombat);if(selection.sourceDirection()==5)loadDirectionAlternatives();}},this::error);}
        private boolean combatColumnIsAutomatic(){for(int row=0;row<TargetSheet.ROWS;row++)if(project.sheet.cells[row][5].override)return false;return true;}
        private void applyCombatSuggestions(PoseSelection[] poses){if(poses!=null&&project.sheet.refreshDetectedCombat(poses)>0){markDirty();refreshCells();}}
