        private void visualChanged(){if(syncingControls)return;VisualSettings v=project.visual;v.cellWidth=(Integer)cellWidth.getValue();v.cellHeight=(Integer)cellHeight.getValue();v.supersample=(Integer)supersample.getValue();v.modelScale=((Number)modelScale.getValue()).doubleValue();v.pitchDegrees=((Number)pitch.getValue()).doubleValue();v.yawOffsetDegrees=((Number)yawOffset.getValue()).doubleValue();v.verticalOffsetPixels=((Number)vertical.getValue()).doubleValue();v.ambient=((Number)ambient.getValue()).doubleValue();v.diffuse=((Number)diffuse.getValue()).doubleValue();v.lightAzimuthDegrees=((Number)lightAzimuth.getValue()).doubleValue();v.lightElevationDegrees=((Number)lightElevation.getValue()).doubleValue();v.materialStyle=(String)materialStyle.getSelectedItem();v.palette=(String)palette.getSelectedItem();v.dithering=(String)dithering.getSelectedItem();v.ditherStrength=((Number)ditherStrength.getValue()).doubleValue();v.preset="Custom";syncingControls=true;preset.setSelectedItem("Custom");syncingControls=false;markDirty();refreshCells();}
